import re
from datetime import date

_SEP = r"([-/.])"
_YMD = re.compile(r"(\d{4})" + _SEP + r"(\d{1,2})\2(\d{1,2})", re.ASCII)
_DMY = re.compile(r"(\d{1,2})" + _SEP + r"(\d{1,2})\2(\d{4})", re.ASCII)

# Written-out forms (applied after lowercasing and whitespace normalization)
_DAY_MONTH_YEAR = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([a-z]+)\.?\s+(\d{4})", re.ASCII
)
_MONTH_DAY_YEAR = re.compile(
    r"([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})", re.ASCII
)

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tue|wed|thu|fri|sat|sun)\.?,?\s+",
    re.ASCII,
)


def _to_iso(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str) -> int | None:
    return _MONTHS.get(name.rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    s = re.sub(r"\s+", " ", s.strip()).lower()
    s = _WEEKDAY_PREFIX.sub("", s, count=1)

    # Year-first numeric: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = _YMD.fullmatch(s)
    if m:
        year, month, day = int(m.group(1)), int(m.group(3)), int(m.group(4))
        return _to_iso(year, month, day)

    # Day-first numeric: DD/MM/YYYY (also accepts - and . separators)
    m = _DMY.fullmatch(s)
    if m:
        day, month, year = int(m.group(1)), int(m.group(3)), int(m.group(4))
        return _to_iso(year, month, day)

    # Day Month Year: "5th March 2024", "5 of March, 2024", "5 mar. 2024"
    m = _DAY_MONTH_YEAR.fullmatch(s)
    if m:
        month = _month_number(m.group(2))
        if month is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), month, int(m.group(1)))

    # Month Day Year: "March 5th, 2024", "mar 5 2024"
    m = _MONTH_DAY_YEAR.fullmatch(s)
    if m:
        month = _month_number(m.group(1))
        if month is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), month, int(m.group(2)))

    return "INVALID"

import re
from datetime import date

INVALID = "INVALID"

_MON = (
    r"(?P<mon>jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|"
    r"jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?"
)
_MONTH_NUM = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

_WEEKDAY = (
    r"(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|"
    r"mon|tues?|wed|thur?s?|fri|sat|sun)"
)
# Leading weekday: "Tuesday, March 5, 2024" / "Tue 5 Mar 2024"
_LEAD_WEEKDAY = re.compile(rf"^{_WEEKDAY}\.?,?\s+", re.IGNORECASE)
# Trailing weekday: "March 5, 2024 (Tuesday)" / "March 5, 2024, Tue"
_TRAIL_WEEKDAY = re.compile(rf",?\s*\(?{_WEEKDAY}\)?\.?$", re.IGNORECASE)


def _make(year: int, month: int, day: int) -> str:
    """Return ISO date string if the calendar date exists, else INVALID."""
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return INVALID


def _strip_weekday(t: str) -> str:
    t = _LEAD_WEEKDAY.sub("", t, count=1)
    t = _TRAIL_WEEKDAY.sub("", t, count=1)
    return t.strip()


def parse(s: str) -> str:
    if not isinstance(s, str):
        return INVALID

    t = " ".join(s.strip().split())
    if not t:
        return INVALID

    t = _strip_weekday(t)
    if not t:
        return INVALID

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric D?D/M?M/YYYY (also - and .).
    # Convention: ambiguous values are day-first (DD/MM/YYYY).
    # Month-first (MM/DD/YYYY) is used only when the second field cannot be a month.
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        a, b, year = int(m.group(1)), int(m.group(3)), int(m.group(4))
        if b > 12 and a <= 12:
            month, day = a, b          # MM/DD/YYYY (unambiguous)
        else:
            day, month = a, b          # DD/MM/YYYY (default, includes ambiguous)
        return _make(year, month, day)

    # 5 March 2021, 5-Mar-2021, 5th of March 2021 (optional "of")
    m = re.fullmatch(
        rf"(\d{{1,2}})(?:st|nd|rd|th)?(?:\s+of)?[\s\-]+{_MON}[\s\-,]+(\d{{4}})",
        t,
        re.IGNORECASE,
    )
    if m:
        return _make(int(m.group(3)), _MONTH_NUM[m.group("mon")[:3].lower()], int(m.group(1)))

    # March 5, 2021 / Mar 5 2021 / March 5th, 2021
    m = re.fullmatch(
        rf"{_MON}[\s\-]+(\d{{1,2}})(?:st|nd|rd|th)?,?[\s\-]+(\d{{4}})",
        t,
        re.IGNORECASE,
    )
    if m:
        return _make(int(m.group(3)), _MONTH_NUM[m.group("mon")[:3].lower()], int(m.group(2)))

    return INVALID

