_ORD = r"(?:st|nd|rd|th)?"

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "Thurs ".
# Longer alternatives come first so full names win over prefixes.
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
