        return date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return INVALID


def _month_num(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def _normalize(s: str) -> str:
    t = re.sub(r"\s+", " ", s.strip())
    t = _WEEKDAY_PREFIX.sub("", t, count=1)
    return t.strip()


def parse(s: str) -> str:
    if not isinstance(s, str):
        return INVALID

    t = _normalize(s)
    if not t:
        return INVALID

    # ISO-like year-first: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact: YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric day-first: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        return _make(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # Month-name first: "Nov 31 2022", "November 31st, 2022", "Nov. 31, 2022"
    m = re.fullmatch(
        r"([A-Za-z]+)\.?,? ?(\d{1,2})" + _ORD + r",? ?(\d{4})", t
    )
    if m:
        mon = _month_num(m.group(1))
        if mon is None:
            return INVALID
        return _make(int(m.group(3)), mon, int(m.group(2)))

    # Day-first with month name: "31 Nov 2022", "31st November, 2022", "31-Nov-2022"
    m = re.fullmatch(
        r"(\d{1,2})" + _ORD + r"[ -]?([A-Za-z]+)\.?,?[ -]?(\d{4})", t
    )
    if m:
        mon = _month_num(m.group(2))
        if mon is None:
            return INVALID
        return _make(int(m.group(3)), mon, int(m.group(1)))

    return INVALID

