)


def _to_iso(year: int, month: int, day: int) -> str:
    """Return ISO date string if the date exists, else 'INVALID'."""
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _clean(s: str) -> str:
    s = s.strip()
    s = re.sub(r"\s+", " ", s)
    # Remove ordinal suffixes after digits: 1st, 2nd, 3rd, 4th
    s = re.sub(r"(?<=\d)(st|nd|rd|th)\b", "", s, flags=re.IGNORECASE)
    # Commas act as separators
    s = s.replace(",", " ")
    s = re.sub(r"\s+", " ", s).strip()
    # Drop a leading or trailing weekday name, e.g. "Tuesday March 5 2024"
    s = re.sub(rf"^{_WEEKDAY}\b\.?\s+", "", s, flags=re.IGNORECASE)
    s = re.sub(rf"\s+{_WEEKDAY}\b\.?$", "", s, flags=re.IGNORECASE)
    return s.strip()


def _month_num(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = _clean(s)
    if not t:
        return "INVALID"

    # ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", t)
    if m:
        return _to_iso(int(m[1]), int(m[2]), int(m[3]))

    # Numeric day-first: DD-MM-YYYY, DD/MM/YYYY, DD.MM.YYYY
    m = re.fullmatch(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})", t)
    if m:
        return _to_iso(int(m[3]), int(m[2]), int(m[1]))

    # Day Month Year: "5 March 2024", "5 Mar. 2024"
    m = re.fullmatch(r"(\d{1,2}) ([A-Za-z]+\.?) (\d{4})", t)
    if m:
        month = _month_num(m[2])
        if month is None:
            return "INVALID"
        return _to_iso(int(m[3]), month, int(m[1]))

    # Month Day Year: "March 5 2024", "Mar 5 2024"
    m = re.fullmatch(r"([A-Za-z]+\.?) (\d{1,2}) (\d{4})", t)
    if m:
        month = _month_num(m[1])
        if month is None:
            return "INVALID"
        return _to_iso(int(m[3]), month, int(m[2]))

    return "INVALID"

import re
from datetime import date

_MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]

_MONTHS = {}
for _i, _full in enumerate(_MONTH_NAMES, 1):
    _MONTHS[_full] = _i
    _MONTHS[_full[:3]] = _i
_MONTHS["sept"] = 9

_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)

# Compiled patterns (ASCII digits only; input is matched as a whole string).
_YMD_NUMERIC = re.compile(r"(\d{4})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{1,2})", re.ASCII)
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})", re.ASCII)
# Day-first numeric: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY (same separator throughout).
_DMY_NUMERIC = re.compile(
    r"(\d{1,2})\s*([-/.])\s*(\d{1,2})\s*\2\s*(\d{4})", re.ASCII
)
_DMY_NAMED = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?[\s-]+([A-Za-z]+)\.?,?[\s-]+(\d{4})",
    re.ASCII | re.IGNORECASE,
)
_MDY_NAMED = re.compile(
    r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})",
    re.ASCII | re.IGNORECASE,
)


def _make(year: int, month: int, day: int) -> str:
    """Return ISO date string if (year, month, day) is a real calendar date, else 'INVALID'."""
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return "INVALID"


def _normalize(s: str) -> str:
    """Collapse whitespace and drop a leading weekday name, if any."""
    t = " ".join(s.strip().split())
    t = _WEEKDAY_PREFIX.sub("", t, count=1)
    return t


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = _normalize(s)
    if not t:
        return "INVALID"

    # Year-first numeric: YYYY-MM-DD, YYYY/M/D, YYYY.MM.DD (padding optional)
    m = _YMD_NUMERIC.fullmatch(t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Compact: YYYYMMDD
    m = _COMPACT.fullmatch(t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Day-first numeric: DD/MM/YYYY, D-M-YYYY, DD.MM.YYYY (ambiguous slashes read as day/month)
    m = _DMY_NUMERIC.fullmatch(t)
    if m:
        return _make(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # Day Month Year: "29 Feb 2016", "5th March, 2024", "29-February-2016", "29 Feb. 2016"
    m = _DMY_NAMED.fullmatch(t)
    if m:
        month = _MONTHS.get(m.group(2).lower())
        if month is None:
            return "INVALID"
        return _make(int(m.group(3)), month, int(m.group(1)))

    # Month Day, Year: "Feb 29, 2016", "March 5th 2024", "Sept. 5, 2024"
    m = _MDY_NAMED.fullmatch(t)
    if m:
        month = _MONTHS.get(m.group(1).lower())
        if month is None:
            return "INVALID"
        return _make(int(m.group(3)), month, int(m.group(2)))

    return "INVALID"
